Here's a modern MSTest data-driven test example for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline test cases ---

    [TestMethod]
    [DataRow(10.0, 2, 20.0)]
    [DataRow(0.0, 5, 0.0)]
    [DataRow(9.99, 1, 9.99)]
    [DataRow(5.50, 3, 16.50)]
    [DataRow(100.0, 0, 0.0)]
    public void CalculateTotal_ReturnsExpected(double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.0, 10.0, 90.0)]
    [DataRow(100.0, 0.0, 100.0)]
    [DataRow(100.0, 100.0, 0.0)]
    [DataRow(49.99, 50.0, 24.995)]
    [DataRow(0.0, 25.0, 0.0)]
    public void ApplyDiscount_ReturnsExpected(double price, double discountPct, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPct);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: complex/reusable test cases ---

    [TestMethod]
    [DynamicData(nameof(BulkOrderData), DynamicDataSourceType.Method)]
    public void CalculateTotal_BulkOrders_ReturnsExpected(decimal price, int quantity, decimal expected)
    {
        var result = _calculator.CalculateTotal(price, quantity);
        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> BulkOrderData()
    {
        yield return new object[] { 19.99m, 100, 1999.00m };
        yield return new object[] { 4.50m, 1000, 4500.00m };
        yield return new object[] { 0.01m, 10000, 100.00m };
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData), DynamicDataSourceType.Method)]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void ApplyDiscount_InvalidPercent_Throws(decimal price, decimal discountPct)
    {
        _calculator.ApplyDiscount(price, discountPct);
    }

    private static IEnumerable<object[]> InvalidDiscountData()
    {
        yield return new object[] { 100m, -1m };
        yield return new object[] { 100m, 101m };
        yield return new object[] { 50m, 200m };
    }
}
```

**Key practices shown:**

| Technique | When to use |
|-----------|-------------|
| `[DataRow]` | Simple inline values (primitives only) |
| `[DynamicData]` | Complex types, computed data, or shared cases |
| `DynamicDataSourceType.Method` | Preferred over `Property` for lazy evaluation |

**Notes:**
- `DataRow` only supports compile-time constants, so use `double` and cast to `decimal` there.
- `DynamicData` methods can yield `decimal` directly since they're runtime.
- Name test methods with the pattern `Method_Scenario_Expected`.
- Use `[TestInitialize]` over constructors for setup.

Adjust the expected values and edge cases to match your actual `PriceCalculator` logic.
